algorithm LargestOfVector
    dimension numbers[5] as integer;
    define i as integer;
    define largest as integer;
    for i <- 0 to 4 step 1 do
        read numbers[i];
    endFor
    largest <- numbers[0];
    for i <- 1 to 4 step 1 do
        if numbers[i] > largest then
            largest <- numbers[i];
        endIf
    endFor
    write largest;
endAlgorithm
